public class Property {
    private String name;
    private int value;

    public Property(String name, int value) {
        this.name = name;
        this.value = value;
    }

    public String getName() {
        return name;
    }

    public int getValue() {
        return value;
    }
}

public class TestPropertyUtils {

    public static List<Property> createProperties() {
        List<Property> properties = new ArrayList<>();
        properties.add(new Property("key1", 1));
        properties.add(new Property("key2", 2));
        return properties;
    }

    public static void assertEqual(List<Property> expected, List<Property> actual) {
        assertEquals(expected.size(), actual.size());
        for (int i = 0; i < expected.size(); i++) {
            assertEquals(expected.get(i).getName(), actual.get(i).getName());
            assertEquals(expected.get(i).getValue(), actual.get(i).getValue());
        }
    }

    public static void testPropertyUtils() {
        List<Property> properties = createProperties();
        assertNotNull(properties);
        for (Property property : properties) {
            assertNotNull(property.getName());
            assertNotNull(property.getValue());
        }

        List<Property> expectedProperties = new ArrayList<>();
        expectedProperties.add(new Property("key1", 1));
        expectedProperties.add(new Property("key2", 2));
        assertEquals(expectedProperties, createProperties());

        List<Property> actualProperties = new ArrayList<>();
        actualProperties.add(new Property("key3", 3));
        actualProperties.add(new Property("key4", 4));
        assertEqual(expectedProperties, actualProperties);
    }
}
